head.script:
scwin.init = function() {
    var jsonData = [{
        col1: "sample"
    }];
    dataList1.setJSON(jsonData);
};
scwin.grd_oncellclick = function(row, col) { //debugger;
    //console.log(`oncellclick ${row} , ${col}`);
    //alert("oncellclick######" +row+"#######"+col );
};
scwin.grd_oncelldblclick = function(row, col) { //debugger;
    //console.log(`oncelldblclick ${row} , ${col}`);
    //alert("oncelldblclick######" +row+"#######"+col );
    log = row;
    log1 = col;
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 name2항목의 컬럼을 마우스로 더블클릭한다.
    //1. After running the sample, double-click the column of name2 item with the mouse.
    //Verify step 1. The oncelldblclick 0, 0 value is displayed in the notification window.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grd_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == '0'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log1 == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = ""; window.log1 = "";
    scwin.init();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 02-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
